package thaumichorizons;

import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.*;
import net.minecraft.world.entity.npc.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.phys.AABB;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.research.*;

@GameTestHolder(ThaumicHorizons.ID)
@PrefixGameTestTemplate(false)
public final class SoulGameTests {
    static SoulMachine sieve(GameTestHelper h){h.setBlock(new BlockPos(2,2,2),Souls.SIEVE.get());return h.getBlockEntity(new BlockPos(2,2,2));}
    @GameTest(template="test/platform") public static void eightSoulSandProduceOneSoulAcrossSaveReload(GameTestHelper h){
        var sieve=sieve(h);h.setBlock(new BlockPos(2,3,2),Souls.FORGE.get());SoulMachine forge=h.getBlockEntity(new BlockPos(2,3,2));h.setBlock(new BlockPos(3,3,2),thaumcraft.registry.ModBlocks.WARDED_JAR.get());thaumcraft.essentia.JarBlockEntity jar=h.getBlockEntity(new BlockPos(3,3,2));jar.addToContainer(Aspect.MIND,12);
        h.setBlock(new BlockPos(2,4,2),thaumcraft.registry.ModBlocks.ESSENTIA_TUBE.get());h.setBlock(new BlockPos(3,4,2),thaumcraft.registry.ModBlocks.ESSENTIA_TUBE.get());thaumcraft.essentia.TubeBlockEntity first=h.getBlockEntity(new BlockPos(2,4,2)),second=h.getBlockEntity(new BlockPos(3,4,2));
        for(int i=0;i<200&&forge.essentia<3000;i++){thaumcraft.essentia.TubeBlockEntity.tick(h.getLevel(),first.getBlockPos(),first.getBlockState(),first);thaumcraft.essentia.TubeBlockEntity.tick(h.getLevel(),second.getBlockPos(),second.getBlockState(),second);SoulMachine.tick(h.getLevel(),forge.getBlockPos(),forge.getBlockState(),forge);}h.assertValueEqual(forge.essentia,3000,"Mind did not travel through two Thaumcraft pipes from jar to forge");sieve.inventory.setStackInSlot(0,new ItemStack(Items.SOUL_SAND,8));
        for(int i=0;i<9600;i++){
            thaumcraft.essentia.TubeBlockEntity.tick(h.getLevel(),first.getBlockPos(),first.getBlockState(),first);thaumcraft.essentia.TubeBlockEntity.tick(h.getLevel(),second.getBlockPos(),second.getBlockState(),second);SoulMachine.tick(h.getLevel(),forge.getBlockPos(),forge.getBlockState(),forge);sieve.extract();
            if(i==4319){
                var savedSieve=sieve.saveWithFullMetadata(h.getLevel().registryAccess());var savedForge=forge.saveWithFullMetadata(h.getLevel().registryAccess());
                var restoredSieve=new SoulMachine(sieve.getBlockPos(),sieve.getBlockState());restoredSieve.loadWithComponents(savedSieve,h.getLevel().registryAccess());restoredSieve.setLevel(h.getLevel());h.getLevel().setBlockEntity(restoredSieve);sieve=restoredSieve;
                var restoredForge=new SoulMachine(forge.getBlockPos(),forge.getBlockState());restoredForge.loadWithComponents(savedForge,h.getLevel().registryAccess());restoredForge.setLevel(h.getLevel());h.getLevel().setBlockEntity(restoredForge);forge=restoredForge;
                h.assertValueEqual(forge.progress,4320,"partial soul lost on reload");
            }
        }
        h.assertValueEqual(forge.souls,1,"eight sand did not assemble one soul");h.assertValueEqual(forge.progress,0,"wrong soul bit threshold");h.assertTrue(sieve.inventory.getStackInSlot(0).isEmpty()&&sieve.ticksLeft==0,"wrong soul sand consumption");
        int sand=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(sieve.getBlockPos()).inflate(2),e->e.getItem().is(Items.SAND)).stream().mapToInt(e->e.getItem().getCount()).sum();h.assertValueEqual(sand,8,"sand byproduct lost or duplicated");h.assertValueEqual((12-jar.getAmount()-first.getEssentiaAmount(Direction.DOWN)-second.getEssentiaAmount(Direction.DOWN))*1000-forge.essentia,9600,"Mind fuel accounting changed");h.succeed();
    }
    @GameTest(template="test/platform") public static void sievePausesForMissingAndFullReceivers(GameTestHelper h){
        var sieve=sieve(h);sieve.inventory.setStackInSlot(0,new ItemStack(Items.SOUL_SAND,2));sieve.extract();h.assertTrue(sieve.ticksLeft==1200&&sieve.inventory.getStackInSlot(0).getCount()==1&&!sieve.extracting,"unconnected sieve used soul bits");
        h.setBlock(new BlockPos(2,3,2),Souls.FORGE.get());SoulMachine forge=h.getBlockEntity(new BlockPos(2,3,2));sieve.extract();h.assertValueEqual(sieve.ticksLeft,1200,"unpowered forge consumed bits");forge.essentia=1000;forge.souls=16;sieve.extract();h.assertValueEqual(sieve.ticksLeft,1200,"full forge consumed bits");forge.souls=15;sieve.extract();h.assertTrue(sieve.extracting&&sieve.ticksLeft==1199&&forge.progress==1&&forge.essentia==999,"valid receiver did not resume");h.succeed();
    }
    @GameTest(template="test/platform") public static void forgeOnlyDrawsMindFromTopAndStopsAtThreeThousand(GameTestHelper h){
        h.setBlock(new BlockPos(2,2,2),Souls.FORGE.get());SoulMachine forge=h.getBlockEntity(new BlockPos(2,2,2));h.assertValueEqual(forge.addEssentia(Aspect.MIND,1,Direction.DOWN),0,"bottom input accepted");h.assertValueEqual(forge.addEssentia(Aspect.LIFE,1,Direction.UP),0,"wrong aspect accepted");for(int i=0;i<3;i++)h.assertValueEqual(forge.addEssentia(Aspect.MIND,64,Direction.UP),1,"more than one aspect consumed per insertion");h.assertValueEqual(forge.essentia,3000,"wrong thousandths conversion");h.assertValueEqual(forge.addEssentia(Aspect.MIND,1,Direction.UP),0,"fuel overfilled");h.assertValueEqual(forge.getSuctionAmount(Direction.UP),0,"full tank suction");forge.essentia=2999;h.assertValueEqual(forge.getSuctionAmount(Direction.UP),128,"refill suction");h.succeed();
    }
    @GameTest(template="test/platform") public static void inspiratronConsumesPaperOnceAndRespectsAutomation(GameTestHelper h){
        h.setBlock(new BlockPos(2,2,2),Souls.INSPIRATRON.get());SoulMachine machine=h.getBlockEntity(new BlockPos(2,2,2));machine.inventory.setStackInSlot(0,new ItemStack(Items.PAPER,2));machine.progress=99;h.getLevel().random.setSeed(69421);for(int i=0;i<1000&&machine.inventory.getStackInSlot(1).isEmpty();i++)machine.addSoulBits(1);
        h.assertTrue(machine.inventory.getStackInSlot(1).is(thaumcraft.registry.ModItems.KNOWLEDGE_FRAGMENT.get())&&machine.inventory.getStackInSlot(1).getCount()==1,"knowledge fragment missing");h.assertValueEqual(machine.inventory.getStackInSlot(0).getCount(),1,"paper consumption");h.assertTrue(machine.automation().extractItem(0,1,false).isEmpty(),"automation stole input");h.assertTrue(machine.automation().insertItem(1,new ItemStack(Items.PAPER),false).is(Items.PAPER),"automation inserted output");h.assertTrue(machine.automation().extractItem(1,1,false).is(thaumcraft.registry.ModItems.KNOWLEDGE_FRAGMENT.get()),"automation cannot extract knowledge");h.succeed();
    }
    @GameTest(template="test/platform") public static void sieveSupportsBrainJarAndByproductChest(GameTestHelper h){
        var sieve=sieve(h);h.setBlock(new BlockPos(2,3,2),thaumcraft.registry.ModBlocks.BRAIN_JAR.get());thaumcraft.device.BrainJarBlockEntity brain=h.getBlockEntity(new BlockPos(2,3,2));brain.setXp(brain.XP_MAX);sieve.inventory.setStackInSlot(0,new ItemStack(Items.SOUL_SAND));sieve.extract();h.assertValueEqual(sieve.ticksLeft,1200,"full brain jar consumed fuel");
        brain.setXp(0);h.setBlock(new BlockPos(2,1,2),net.minecraft.world.level.block.Blocks.CHEST);h.getLevel().random.setSeed(45667);for(int i=0;i<1200;i++)sieve.extract();h.assertTrue(brain.getXp()>0&&brain.getXp()<100,"brain XP production");net.minecraft.world.level.block.entity.ChestBlockEntity chest=h.getBlockEntity(new BlockPos(2,1,2));h.assertTrue(chest.getItem(0).is(Items.SAND)&&chest.getItem(0).getCount()==1,"sand byproduct not inserted below");h.succeed();
    }
    @GameTest(template="test/platform") public static void bottledSoulAnimatesEffigyWithProfessionAndOneReturnedJar(GameTestHelper h){
        var vat=VatGameTests.vat(h);vat.mode=4;var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,Souls.soulJar(VillagerProfession.LIBRARIAN));vat.interact(player,InteractionHand.MAIN_HAND,false);
        h.assertTrue(vat.mode==0&&vat.occupant() instanceof Villager v&&v.getVillagerData().getProfession()==VillagerProfession.LIBRARIAN,"soul did not animate villager with stored profession");h.assertTrue(!Souls.isSoul(player.getMainHandItem()),"soul jar not consumed");int jars=0;for(var stack:player.getInventory().items)if(stack.is(thaumcraft.registry.ModBlocks.WARDED_JAR.get().asItem()))jars+=stack.getCount();h.assertValueEqual(jars,1,"wrong returned jar count");h.succeed();
    }
    @GameTest(template="test/platform") public static void bodyWithTwoInfusionsRefusesSoulWithoutConsumption(GameTestHelper h){var vat=VatGameTests.vat(h);vat.mode=4;vat.shellInfusions[0]=3;vat.shellInfusions[1]=5;var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,Souls.soulJar(VillagerProfession.CLERIC));vat.interact(player,InteractionHand.MAIN_HAND,false);h.assertTrue(vat.mode==4&&Souls.isSoul(player.getMainHandItem())&&vat.shellInfusions[1]==5,"incompatible body consumed soul or lost infusion");h.succeed();}
    @GameTest(template="test/platform") public static void originalSelfInfusionProgressionHasEveryParent(GameTestHelper h){
        for(String key:new String[]{"soulExtractor","soulKnowledge","soulAssembler","cloneVillager","nightmare","cloneSelf","selfInfusion"}){var r=ResearchCategories.getResearch(key);h.assertTrue(r!=null,"missing progression step "+key);for(String parent:r.parents())h.assertTrue(ResearchCategories.getResearch(parent)!=null,"unreachable parent "+parent);}
        h.assertTrue(ResearchCategories.getResearch("soulExtractor").itemTriggers().contains(net.minecraft.resources.ResourceLocation.withDefaultNamespace("soul_sand")),"hidden soul research cannot be discovered by scanning soul sand");h.assertTrue(ResearchCategories.getResearch("soulKnowledge").isConcealed()&&ResearchCategories.getResearch("soulAssembler").isConcealed(),"soul research revealed before prerequisites");
        var recipe=(thaumcraft.crafting.InfusionRecipe)thaumcraft.crafting.TcRecipes.get("TH:recipeSoulSieve");h.assertTrue(recipe.components().get(1).test(new ItemStack(thaumcraft.registry.ModItems.ENCHANTED_FABRIC.get())),"legacy resource metadata seven must be enchanted fabric");h.assertTrue(!recipe.components().get(1).test(new ItemStack(thaumcraft.registry.ModItems.QUICKSILVER.get())),"quicksilver substitutes for enchanted fabric");h.succeed();
    }
    @GameTest(template="test/platform") public static void wandReleaseShattersJarAndPreservesPetAndInfusions(GameTestHelper h){
        var pos=new BlockPos(2,2,2);h.setBlock(pos,Specimens.JAR.get());SpecimenJarEntity jar=h.getBlockEntity(pos);var wolf=net.minecraft.world.entity.EntityType.WOLF.create(h.getLevel());wolf.setTame(true,false);Infusions.add(wolf,4,null,new AspectList());jar.stack=Specimens.write(wolf);var player=h.makeMockPlayer(GameType.SURVIVAL);h.assertTrue(jar.release(player),"wand release failed");var released=h.getLevel().getEntity(wolf.getUUID());h.assertTrue(released instanceof net.minecraft.world.entity.animal.Wolf pet&&pet.getOwnerUUID().equals(player.getUUID())&&Infusions.has(pet,4),"jar release changed identity, pet owner or infusions");h.assertTrue(h.getLevel().isEmptyBlock(h.absolutePos(pos)),"released jar did not shatter");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(pos)).inflate(2),e->e.getItem().is(Content.item("specimen_jar"))).isEmpty(),"shattered jar dropped a second stored creature");h.succeed();
    }
    @GameTest(template="test/platform") public static void bottledSoulsCannotBeReleasedAsCreaturesOrDuplicated(GameTestHelper h){
        h.setBlock(new BlockPos(2,2,2),Souls.FORGE.get());SoulMachine forge=h.getBlockEntity(new BlockPos(2,2,2));forge.souls=1;var player=h.makeMockPlayer(GameType.SURVIVAL);player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(thaumcraft.registry.ModBlocks.WARDED_JAR.get(),2));h.assertTrue(forge.bottle(player,player.getMainHandItem()),"soul bottling failed");h.assertValueEqual(forge.souls,0,"bottled soul not removed");h.assertValueEqual(player.getMainHandItem().getCount(),1,"wrong empty jar consumption");h.assertTrue(!forge.bottle(player,player.getMainHandItem()),"empty forge duplicated soul");ItemStack soul=player.getInventory().items.stream().filter(Souls::isSoul).findFirst().orElseThrow();h.assertTrue(Specimens.read(soul,h.getLevel())==null,"soul loaded as entity specimen");h.setBlock(new BlockPos(3,2,2),Specimens.JAR.get());SpecimenJarEntity jar=h.getBlockEntity(new BlockPos(3,2,2));jar.stack=soul;h.assertTrue(!jar.release(player)&&Souls.isSoul(jar.stack),"wand released or consumed a pure soul");h.succeed();
    }
    @GameTest(template="test/platform") public static void legacyThaumcraftMetadataAndToolDamageMatchOriginalRecipes(GameTestHelper h){
        var tags=AspectRegistry.active();var ink=tags.getObjectTags(Content.item("ink_egg"));h.assertTrue(ink!=null&&ink.getAmount(Aspect.SLIME)==2&&ink.getAmount(Aspect.DARKNESS)==2&&ink.visSize()==4,"original ink egg aspects replaced by dye/recipe inference");
        var beacon=tags.getObjectTags(Vats.BEACON.get().asItem());h.assertTrue(beacon!=null&&beacon.getAmount(Aspect.SOUL)==8&&beacon.getAmount(Aspect.TRAVEL)==8&&beacon.getAmount(Aspect.TRAP)==8&&beacon.getAmount(Aspect.LIGHT)==8,"original beacon scan aspects");
        var vatTags=tags.getObjectTags(Vats.GLASS.get().asItem());h.assertTrue(Vats.GLASS.get().asItem()!=Items.AIR&&vatTags!=null&&vatTags.getAmount(Aspect.HEAL)==1&&vatTags.getAmount(Aspect.MECHANISM)==1,"formed vat lost its original scanner tags");
        var familiarTags=tags.getEntityTags(Species.FAMILIAR.get().create(h.getLevel()));h.assertTrue(familiarTags!=null&&familiarTags.getAmount(Aspect.BEAST)==3&&familiarTags.getAmount(Aspect.MAGIC)==3&&familiarTags.getAmount(Aspect.AURA)==3,"familiar cannot be scanned with original aspects");
        h.assertTrue(Vats.raw(0,0,0).is(thaumcraft.registry.ModBlocks.GREATWOOD_PLANKS.get())&&Vats.raw(1,3,1).is(thaumcraft.registry.ModBlocks.ALCHEMICAL_CONSTRUCT.get()),"legacy vat uses greatwood planks and alchemical constructs, not vis relays or reservoirs");
        var dynamo=(thaumcraft.crafting.InfusionRecipe)thaumcraft.crafting.TcRecipes.get("TH:recipeVisDynamo");h.assertTrue(dynamo.components().get(2).test(new ItemStack(thaumcraft.registry.ModBlocks.GREATWOOD_PLANKS.get())),"wooden device metadata six is not greatwood planks");
        var essentia=(thaumcraft.crafting.InfusionRecipe)thaumcraft.crafting.TcRecipes.get("TH:recipeEssentiaDynamo");h.assertTrue(essentia.components().get(1).test(new ItemStack(thaumcraft.registry.ModBlocks.ALCHEMICAL_CONSTRUCT.get()))&&essentia.components().get(4).test(new ItemStack(thaumcraft.registry.ModBlocks.ALCHEMICAL_CENTRIFUGE.get())),"legacy metal device nine / tube two mapping incorrect");
        var blood=(thaumcraft.crafting.InfusionRecipe)thaumcraft.crafting.TcRecipes.get("TH:recipeBloodInfuser");h.assertTrue(blood.components().get(2).test(new ItemStack(thaumcraft.registry.ModBlocks.ESSENTIA_BUFFER.get())),"tube metadata four is not essentia buffer");
        var heart=VatRecipes.get("self_5");h.assertTrue(heart.ingredients().get(0).test(new ItemStack(thaumcraft.registry.ModBlocks.SILVERWOOD_SAPLING.get()))&&heart.ingredients().get(2).test(new ItemStack(thaumcraft.registry.ModBlocks.SHIMMERLEAF.get())),"plant metadata one / two mapping incorrect");
        var tumor=VatRecipes.get("self_8");h.assertTrue(tumor.ingredients().get(0).test(new ItemStack(thaumcraft.registry.ModBlocks.FLESH_BLOCK.get()))&&tumor.ingredients().get(3).test(new ItemStack(thaumcraft.registry.ModBlocks.OBSIDIAN_TOTEM.get())),"taint metadata two / cosmetic solid zero mapping incorrect");
        var shears=new ItemStack(Items.SHEARS);var recipe=VatRecipes.get("species_self_shearing_sheep_sheep");h.assertTrue(recipe.ingredients().get(0).test(shears),"new shears rejected");shears.setDamageValue(1);h.assertTrue(!recipe.ingredients().get(0).test(shears),"damaged tool substitutes for metadata-zero ingredient");h.succeed();
    }
}
